package javadsa;

public class square_pattern2 {

	public static void main(String[] args) {
		pattern(5);
	}
		// TODO Auto-generated method stub
		static void pattern(int n ) {
			for(int row=1;row<=n;row++ ) {
				for(int col=1;col<=n;col++) {
					System.out.print("*");
					
				}
				System.out.println();
			}
		
	

	}

}
